contract InvMutTest {
    C c;

    constructor() payable { c = new C{value: 1 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bytes32 guess_, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount == 1 ether, "amount must be 1 ether");
        require(address(this).balance >= amount, "not enough balance");

        // Snapshot the balance before any state-changing call.
        uint beforeBalance = address(this).balance;

        // First call: lock in a guess. This must succeed because amount is exactly 1 ether.
        c.lockInGuess{value: amount}(guess_); if (__ESBMC_reverted()) return;

        // Second call: attempt to settle the guess immediately.
        // Because settle() requires block.number > guesses[msg.sender].block,
        // and guesses[msg.sender].block is set to block.number + 1 by lockInGuess,
        // this call must always revert in the same block.
        bool reverted = false;
        c.settle(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule: settle() immediately after lockInGuess in the same block
        // must revert, so no Ether can be received from c.
        assert(reverted && address(this).balance == beforeBalance - amount);
    }

    receive() external payable {}
}

